def clamp(value, low, high):
    if low > high:
        raise ValueError("invalid bounds")
    return max(low, min(value, high))

def unique(items):
    result = []
    for item in items:
        if item not in result:
            result.append(item)
    return result

from pricing import DISCOUNT_PERCENT

def invoice_total(rows):
    return sum(quantity * price for quantity, price in rows) * (1 - DISCOUNT_PERCENT / 100)

