const { test } = require('node:test');
const assert = require('node:assert/strict');
const { paginate } = require('./solution');
test('pagination', () => {
 const a = [1,2,3,4,5];
 assert.deepEqual(paginate(a, 2, 2), [3,4]);
 assert.deepEqual(paginate(a, 3, 2), [5]);
 assert.deepEqual(paginate(a, 9, 2), []);
 assert.deepEqual(a, [1,2,3,4,5]);
 for (const [p,s] of [[0,2], [1,0], [1.5,2], [1,2.5]]) assert.throws(() => paginate(a,p,s), RangeError);
});

